begin;
create temporary table guide_checks(label text);
grant select,insert on guide_checks to anon,authenticated;
create function pg_temp.ok_guide(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAILED: %',label;end if;insert into guide_checks values(label);end $$;
create function pg_temp.reject_guide(command text,expected text,label text) returns void language plpgsql as $$declare code text;begin begin execute command;exception when others then get stacked diagnostics code=returned_sqlstate;end;perform pg_temp.ok_guide(code=expected,label);end $$;
insert into auth.users(id,email,raw_user_meta_data,email_confirmed_at) values
 ('75000000-0000-4000-8000-000000000001','guide-v1@example.invalid','{"role":"vendor","name":"Guide vendor"}',now()),
 ('75000000-0000-4000-8000-000000000002','guide-v2@example.invalid','{"role":"vendor","name":"Other guide vendor"}',now()),
 ('75000000-0000-4000-8000-000000000003','guide-c@example.invalid','{"role":"customer","name":"Guide customer"}',now());
set local role anon;
select set_config('request.jwt.claims','{}',true);
select pg_temp.reject_guide($q$select public.get_vendor_guide_state('75000000-0000-4000-8000-000000000001')$q$,'42501','anonymous cannot read guide');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"75000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select pg_temp.reject_guide($q$select public.get_vendor_guide_state('75000000-0000-4000-8000-000000000003')$q$,'42501','customer cannot access vendor guide');
select pg_temp.reject_guide($q$select public.save_vendor_guide_progress('75000000-0000-4000-8000-000000000003','completed',6)$q$,'42501','customer cannot write vendor progress');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"75000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select pg_temp.ok_guide(public.get_vendor_guide_state('75000000-0000-4000-8000-000000000001')->>'status'='pending','new vendor starts pending');
select pg_temp.reject_guide($q$select public.get_vendor_guide_state('75000000-0000-4000-8000-000000000002')$q$,'42501','cannot request another account progress');
select pg_temp.reject_guide($q$select public.save_vendor_guide_progress('75000000-0000-4000-8000-000000000002','completed',6)$q$,'42501','account switch cannot write to wrong UID');
select pg_temp.reject_guide($q$insert into public.vendor_guide_progress(vendor_id,status) values('75000000-0000-4000-8000-000000000001','skipped')$q$,'42501','direct writes unavailable');
select pg_temp.reject_guide($q$select public.save_vendor_guide_progress('75000000-0000-4000-8000-000000000001','completed',2)$q$,'22023','completion requires final step');
select pg_temp.ok_guide((public.save_vendor_guide_progress('75000000-0000-4000-8000-000000000001','in_progress',3)->>'last_step')::int=3,'partial tour persists');
select pg_temp.ok_guide((public.save_vendor_guide_progress('75000000-0000-4000-8000-000000000001','in_progress',1)->>'last_step')::int=3,'late writes cannot rewind furthest step');
select pg_temp.ok_guide(public.save_vendor_guide_progress('75000000-0000-4000-8000-000000000001','skipped',3)->>'status'='skipped','skip persists');
select pg_temp.ok_guide(public.save_vendor_guide_progress('75000000-0000-4000-8000-000000000001','completed',6)->>'status'='completed','completion persists');
select pg_temp.ok_guide(public.save_vendor_guide_progress('75000000-0000-4000-8000-000000000001','skipped',2)->>'status'='completed','late dismissal cannot erase completion');
select pg_temp.ok_guide((public.save_vendor_guide_progress('75000000-0000-4000-8000-000000000001','in_progress',0,true)->>'last_step')::int=0,'explicit replay restarts progress');
select pg_temp.ok_guide((public.get_vendor_setup_checklist('75000000-0000-4000-8000-000000000001')->>'business_count')::int=0,'practice creates no business');
select pg_temp.ok_guide((public.get_vendor_setup_checklist('75000000-0000-4000-8000-000000000001')->>'service_count')::int=0,'practice creates no service');
select pg_temp.ok_guide((public.get_vendor_setup_checklist('75000000-0000-4000-8000-000000000001')->>'profile_complete')::boolean=false,'guide completion cannot complete actual profile');
update public.vendors set phone='+919999990001' where id='75000000-0000-4000-8000-000000000001';
select pg_temp.ok_guide((public.get_vendor_setup_checklist('75000000-0000-4000-8000-000000000001')->>'profile_complete')::boolean,'checklist reflects actual profile');
reset role;
insert into public.category_nodes(id,name,slug) values('75000000-0000-4000-8000-000000000010','Guide category','guide-fixture-category');
set local role authenticated;
insert into public.businesses(id,vendor_id,name,primary_category_id) values('75000000-0000-4000-8000-000000000020','75000000-0000-4000-8000-000000000001','Guide business','75000000-0000-4000-8000-000000000010');
insert into public.business_category_nodes(business_id,category_node_id) values('75000000-0000-4000-8000-000000000020','75000000-0000-4000-8000-000000000010');
insert into public.services(id,vendor_id,business_id,category_node_id,name,slug,price) values('75000000-0000-4000-8000-000000000030','75000000-0000-4000-8000-000000000001','75000000-0000-4000-8000-000000000020','75000000-0000-4000-8000-000000000010','Guide service','guide-fixture-service',100);
select pg_temp.ok_guide((public.get_vendor_setup_checklist('75000000-0000-4000-8000-000000000001')->>'business_count')::int=1,'real business updates checklist');
select pg_temp.ok_guide((public.get_vendor_setup_checklist('75000000-0000-4000-8000-000000000001')->>'service_count')::int=1,'real service updates checklist');
select set_config('request.jwt.claims','{"sub":"75000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select pg_temp.ok_guide(not exists(select 1 from public.vendor_guide_progress),'other vendor cannot select private progress');
select pg_temp.ok_guide(public.get_vendor_guide_state('75000000-0000-4000-8000-000000000002')->>'status'='pending','other vendor remains independent');
select pg_temp.ok_guide((public.get_vendor_setup_checklist('75000000-0000-4000-8000-000000000002')->>'service_count')::int=0,'other vendor setup stays private');
reset role;
update auth.users set banned_until=now()+interval '1 day' where id='75000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"75000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select pg_temp.reject_guide($q$select public.get_vendor_setup_checklist('75000000-0000-4000-8000-000000000001')$q$,'42501','suspended accounts cannot access checklist');
reset role;
select pg_temp.ok_guide((select relrowsecurity from pg_class where oid='public.vendor_guide_progress'::regclass),'guide progress RLS enabled');
select pg_temp.ok_guide(not exists(select 1 from pg_publication_tables where schemaname='public' and tablename='vendor_guide_progress'),'private guide rows not directly published');
select count(*) as passed_vendor_guide_checks from guide_checks;
rollback;
